import uk.org.okapibarcode.backend.Ean;
import uk.org.okapibarcode.backend.Upc;
import uk.org.okapibarcode.backend.Symbol;
import uk.org.okapibarcode.backend.HumanReadableLocation;

public class BarcodeTest {
    public static void main(String[] args) throws Exception {
        // Test EAN13 with 12 digits (no check digit)
        System.out.println("=== EAN13 with 12 digits (no check digit) ===");
        testEan13("123456789012");

        // Test EAN13 with 13 digits (with check digit)
        System.out.println("\n=== EAN13 with 13 digits (with check digit) ===");
        testEan13("1234567890128");

        // Test UPCA with 11 digits (no check digit)
        System.out.println("\n=== UPCA with 11 digits (no check digit) ===");
        testUpcA("12345678901");

        // Test UPCA with 12 digits (with check digit)
        System.out.println("\n=== UPCA with 12 digits (with check digit) ===");
        testUpcA("123456789012");
    }

    static void testEan13(String value) throws Exception {
        Ean ean = new Ean(Ean.Mode.EAN13);
        ean.setHumanReadableLocation(HumanReadableLocation.BOTTOM);
        ean.setContent(value);
        System.out.println("Input: " + value);
        System.out.println("Content: " + ean.getContent());
        System.out.println("Human readable: " + ean.getHumanReadableText());
    }

    static void testUpcA(String value) throws Exception {
        Upc upc = new Upc(Upc.Mode.UPCA);
        upc.setHumanReadableLocation(HumanReadableLocation.BOTTOM);
        upc.setContent(value);
        System.out.println("Input: " + value);
        System.out.println("Content: " + upc.getContent());
        System.out.println("Human readable: " + upc.getHumanReadableText());
    }
}
